) AS (
  VALUES 
    (709::BIGINT, 'Muy buen profe, ayuda y explica bien. Pero este semestre hizo las evaluaciones más difíciles que en semestres pasados.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2025-12-17T00:00:00+00:00'::TIMESTAMPTZ, '800fb710e422d8ec7740c018a98431cafb9372c80a555e71a28b16ae250b2a0b'::TEXT, ARRAY[3055]::BIGINT[]),
    (709::BIGINT, 'Es una teja de profesor, hace ejercicios difíciles en clase, comparables al exámen, tiene banco de ejercicios para ayudarse porque el curso no es tan sencillo. Metan con él sin miedo, es muy amable aún si algo intimidante y sabe un cañazo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-20T00:00:00+00:00'::TIMESTAMPTZ, '7b3de5aff0f5d58342536242029a9e7da254655496de9e2d5b3acb0ae127151d'::TEXT, ARRAY[3055]::BIGINT[]),
    (709::BIGINT, 'Excelente profesor. Explica de manera clara y evaluá justamente. Aprovecha el espacio entre clases para realizar ejercicios de calidad para exámenes. No dude en tomar la clase con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'f46ca1416cc34de8f49d6e7c9dca6f44a2210bf4d4fcdf42f2d01bdf90ef4158'::TEXT, ARRAY[3055]::BIGINT[]),
    (709::BIGINT, 'El curso son tres proyectos, siendo el primero el más sencillo pero más tedioso al tener que cablear pero solo se usan combinacionales, los restantes sí tienen bastante dificultad al ocupar secuenciales. Les recomiendo ir a consulta siempre que puedan.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, '05bb7b71f8d10c883d1d18736831023d4820753f567e682317c8f430f3a486e3'::TEXT, ARRAY[3056]::BIGINT[]),
    (709::BIGINT, 'Junto a Juanca los mejores profes de Meca. Demasiado increíble. TQM profe Carlos'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'ed9d24316f995fbe41f8141364486a3a90dc2291183f344d09e82b4da9c1ac45'::TEXT, ARRAY[3055]::BIGINT[]),
    (709::BIGINT, 'No es mala opción, si se interesa en la clase y participa regala puntos y ayuda bastante.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Pocos exámenes']::TEXT[], '2023-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'e704eb7460cf3c89e907c6d97c14cb475b5a0c95ebdfbf25d201324cc639673a'::TEXT, ARRAY[3055]::BIGINT[]),
    (709::BIGINT, 'El profesor califica bastante duro pero explica muy bien la materia durante el curso. En el regreso a clases presenciales, muchas de las evaluaciones fueron remotas lo cual ayudó a que el rendimiento fuera mejor en el curso.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2022-11-25T00:00:00+00:00'::TIMESTAMPTZ, '77be5c268c69a48abeac8d3d162c8a60020c122461f536495e20c3099fc3374c'::TEXT, ARRAY[3055]::BIGINT[]),
    (709::BIGINT, 'Excelente profesor, se nota que le apasiona lo que hace. El curso es duro, pero el profesor ayuda mucho y es consciente de la carga que conlleva el curso. Lo escogería de nuevo sin pensarlo. No pasa lista pero hace actividades al azar en clase por lo que hay que asistir siempre.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Clases excelentes']::TEXT[], '2022-02-10T00:00:00+00:00'::TIMESTAMPTZ, '419146ed1ec3eba70fca2cade6181d2e23d6cfde951320f3332eb986b5e8db34'::TEXT, ARRAY[3055]::BIGINT[]),
    (709::BIGINT, 'Muy buen profesor, explica la materia con claridad y atiende dudas siempre que alguien lo necesite. Califica duro en los exámenes pero es flexible con los reclamos. Hace actividades en cualquier momento en clase, por lo que es importante ir a todas. Su voz enamora'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'c3cdeae00469c1447aa2bf244cfbb2f6e1231aa38b43e366609f84f3c732ba42'::TEXT, ARRAY[3055]::BIGINT[]),
    (709::BIGINT, 'Explica con presentaciones, pero las clases son excelentes. Puede tirar a matar en los exámenes y califica duro, toca hacer los ejercicios del banco e ir a consulta.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2021-11-26T00:00:00+00:00'::TIMESTAMPTZ, '07829eb9e10b246d48db3c6bbd1c677e0d3e6d3090fc81fa0f4f0b0967932ff0'::TEXT, ARRAY[3055]::BIGINT[]),
    (709::BIGINT, 'Un buen profe que atiende rápido y muy bien las dudas, aligera un poco el curso siendo este algo duro.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Da crédito extra']::TEXT[], '2021-02-02T00:00:00+00:00'::TIMESTAMPTZ, 'b53180393488ed62d5804bb6d3ee7f36678edc006874943246f99f4cfcbd1541'::TEXT, ARRAY[3055]::BIGINT[]),
    (709::BIGINT, 'Las clases son muy buenas pero pueden resultar algo pesadas al ser sincrónicas a las 730a.m. El profesor responde muy rápido las consultas y ayuda mucho para el laboratorio si se le consulta.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-20T00:00:00+00:00'::TIMESTAMPTZ, '58e2d5f4dc3ea39981affae865f73eb3961f51d6d16c29e7acef550379110e6f'::TEXT, ARRAY[3055]::BIGINT[]),
    (709::BIGINT, 'Las clases se impartieron de manera sincrónica. Toda la organización del curso y las diferentes evaluaciones, están muy clara de principio a fin. La materia se explica muy bien durante la clase y las consultas se atienden de forma clara. Ayuda con las dudas de laboratorio.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2021-01-20T00:00:00+00:00'::TIMESTAMPTZ, '5b2371678fca465d874aa9e1fc9e8c58f54c048db4ac39fc39a8eacd2d3590f9'::TEXT, ARRAY[3055]::BIGINT[]),
    (709::BIGINT, 'Buen profesor, explica bien la materia y responde prácticamente cualquier duda que tenga sobre la misma gracias a que domina bien los temas del curso. Debido a Covid la evaluación se resumió en muchos quices y 4 tareas. Hay que estudiar y practicar. NO copien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'afd02a25106a0187013321d552f002fec64da28085beb2520ac5b9f6b7de0d59'::TEXT, ARRAY[3055]::BIGINT[]),
    (709::BIGINT, 'El profe es bueno, explica muy bien y en la modalidad virtual se adaptó bastante bien. Califica muy duro, toca hacer práctica y poner atención en clase a ver si no se va en las trampas de examenes y quices.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-07-23T00:00:00+00:00'::TIMESTAMPTZ, '19a673f03ad4f07a4661c60835088c7728d073183eb9d29293800c2bff8f9676'::TEXT, ARRAY[3055]::BIGINT[]),
    (709::BIGINT, 'El profe es excelente explicando. La materia es muy interesante. Sin embargo, los exámenes son algo duros, hay que entender la materia y tener imaginación. Los quices también son algo complicados, aunque si no hay tiempo de hacerlos en clase, los deja para la casa. Las tareas se sacan sencillo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'd38a006d835cb99fe3f2464ea18d1c7402529cd1f224939c852713e548e74495'::TEXT, ARRAY[3055]::BIGINT[]),
    (709::BIGINT, 'Es muy buena gente y explica muy bien. Realmente se preocupa por que uno aprenda y entienda bien los conceptos. Las evaluaciones tienen su dificultad y revisa duro entonces hay que ponerle.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2019-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'acf70b3dfb4ec33471947696ae77c534f073590370699c62444a664a74ff77d1'::TEXT, ARRAY[3055]::BIGINT[]),
    (709::BIGINT, 'Es uno de esos profesores que realmente se preocupa porque el estudiante aprenda. Atiende muy bien las consultas y explica las veces que sea necesario durante la clase. Los exámenes y quices son difíciles pero se aprende bastante.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2019-06-06T00:00:00+00:00'::TIMESTAMPTZ, '612dd1fe5806a8088f12c355360cae45aa296cdf9b57792897af438eeae5d5a9'::TEXT, ARRAY[3055]::BIGINT[]),
    (709::BIGINT, 'Excelente profe, explica super bien y motiva a que uno participe. En consulta ayuda mucho.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-02-15T00:00:00+00:00'::TIMESTAMPTZ, '7ab2ec9063e54d38b12e9c80d58f89a3e3b50806ddd895337a0e857c8a251314'::TEXT, ARRAY[3055]::BIGINT[]),
    (709::BIGINT, 'Excelente profesor, explica muy bien, resuelve las dudas y da "incentivos" a la participación, eso sí, las evaluaciones son bastante duras'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Clases excelentes']::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, '9588620f85485475a84960d60555bf3cf12daacb25dff3671311af1e3320a313'::TEXT, ARRAY[3055]::BIGINT[]),
    (709::BIGINT, 'Es uno de los mejores profes de meca, las clases son excelentes y explica muy bien durante la clase y en consulta. Super recomendado. Los exámenes son difíciles, hay que ponerle.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, '91aeb4f513a636baf82ab0eb25e74873dd09971bc63384f10c6cab272fc5eba1'::TEXT, ARRAY[3055]::BIGINT[]),
    (709::BIGINT, 'Excelente profe, explica muy bien, siempre dispuesto a ayudar a los estudiantes. Deja un proyecto interesante que ayuda a facilita el dominio de la materia. La exigencia del curso es alta, pero con estudiar un poco y poner MUCHA atención en clases se pasa.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, '56f9871ba56af350c4bf2d96164e50b246c7949b6969b0e54d262d346b6cfd45'::TEXT, ARRAY[3055]::BIGINT[]),
    (709::BIGINT, 'El profesor explica muy bien la materia. Las material de clases ayuda mucho. Atiende todas las preguntas en clases y en consulta ayuda bastante. El curso difícil y hay que poner mucha atención a todo lo que se dice en clase.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2018-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'fd8809cde91b853fc7a075a95757bbf714dec01bef45fda9d163a6f1a7079975'::TEXT, ARRAY[3055]::BIGINT[]),
    (709::BIGINT, 'El profe es muy buena gente y domina muy bien la materia pero piensa que todo es sencillo para el estudiante, los exámenes son algo difíciles pero se pasa con poner atención a TODO lo que dice, de fijo lo más mínimo lo pregunta en alguna evaluación.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'b229b29cea7e2bfca8b883b7a54d035f651309f309ec4fe49d54bb15e3a4ceac'::TEXT, ARRAY[3056]::BIGINT[]),
    (709::BIGINT, 'Conoce mucho sobre microcontroladores y microprocesadores. En general de sistemas digitales domina mucho el tema. Sus clases son interesantes y se aprende mucho.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2018-06-07T00:00:00+00:00'::TIMESTAMPTZ, '99f5258be9a7def105579fba190d7bba3c1f2b64dd7fe66f0b372d5bcccc9025'::TEXT, ARRAY[3066]::BIGINT[]),
    (709::BIGINT, 'Excelente profesor, tiene un dominio total de la materia, conoce mucho del área digital, los proyectos son difíciles pero el profesor brinda mucha ayuda. Los exámenes son muy difíciles.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-16T00:00:00+00:00'::TIMESTAMPTZ, 'd8da5526b32b319968782e0d64c6eca710712814c30fc730748649c86b46f6b9'::TEXT, ARRAY[3066]::BIGINT[]),
    (709::BIGINT, 'Excelente curso. Explica muy bien y todo se le entiende. Volvería a tomar un curso con él.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'd05e74953bc1ec003cc950e1cd12e59a889dff23b575f881e22eda25279baf00'::TEXT, ARRAY[3050]::BIGINT[]),
    (709::BIGINT, 'Explica bien y ayuda bastante. Los examenes y quices son rudillos pero acordes con el curso en cuestión. Califica justo'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-07T00:00:00+00:00'::TIMESTAMPTZ, 'f7db823e575c14a2269d9f9a9a3361acf393a10fe7349028ae261363b261cb02'::TEXT, ARRAY[3050]::BIGINT[]),
    (709::BIGINT, 'Muy buen profe. Entre los que dan Lab, la mejor opción. Evalúa justo, aunque la materia en sí es bien ruda. El lab quita tiempo y es cansado, pero él lo sabe y ayuda. Explica bastante bien, y si ve esfuerzo y mejora, se pone suave al evaluar al final. Sabe mucho, hay que aprovechar. Recomendado 100%'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-10T00:00:00+00:00'::TIMESTAMPTZ, '0cf8aad283504c0cb2beecb47d2a78834b2167c3b0d9de81f82f8e08c5224b94'::TEXT, ARRAY[3050]::BIGINT[]),
    (709::BIGINT, 'Es un excelente profe. Lástima que la materia en sí sea tan ruda, pero él ayuda en la mayor medida de lo posible, siempre y cuando uno muestre interés y se esfuerce. La materia al menos es pasable, no como la teoría jajajajajaja aiuda'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('25','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Deja trabajos largos']::TEXT[], '2016-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'f486ebaf121386388afc24c784bae8cb2063805bd4ceeb6c5ca91f0c8da15da1'::TEXT, ARRAY[3050]::BIGINT[]),
    (709::BIGINT, 'Explica muy bien, si uno no entiende saca el tiempo para ayudarle. Los quices y examenes se las traen pero califica justo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-01T00:00:00+00:00'::TIMESTAMPTZ, '0a1a1183c20e505deb41f616700b4ee7bac6c67f74de0d4b20f912f4884d02fc'::TEXT, ARRAY[3050]::BIGINT[]),
    (709::BIGINT, 'Exc profesor. Se le entiende muy bien todo durante sus lecciones, el curso es algo tedioso pero el profesor explica bien. Durante las consultas se entiende bastante de forma individual.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2016-09-24T00:00:00+00:00'::TIMESTAMPTZ, 'ba71ab21d1c0636bbd590a672783f7a8755845d831d7e3dc71db8def220c80df'::TEXT, ARRAY[1279, 1276]::BIGINT[]),
    (709::BIGINT, 'Explica bien, utiliza presentaciones que son del autor del libro pero demuestra un claro dominio del tema, en consulta es igualmente excelente, los exámenes son difíciles pero nada imposible.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Exámenes retadores']::TEXT[], '2016-07-30T00:00:00+00:00'::TIMESTAMPTZ, '9c61de1bf9c0456d10fe9ef21a74d6c5be4e1f2a1d4ea313f36a60933bdcedce'::TEXT, ARRAY[1279, 1276]::BIGINT[]),
    (709::BIGINT, 'Explica bien la materia y el profesor si tiene que explicar 10 veces, 10 veces lo va a hacer. Hay veces se vuelve un poco cansada la clase por la hora pero en general es un buen profe. Recomendado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2016-07-13T00:00:00+00:00'::TIMESTAMPTZ, '8c1dbd160dd2136e7f21cda0932e5c578f5ee0b6d31d2d010c163b877e91a51e'::TEXT, ARRAY[1279, 1276]::BIGINT[]),
    (709::BIGINT, 'La materia es muy interesante, el profesor se le entiende muy bien la clase. Es un curso fácil, pero usualmente uno por lab de lógico no tiene tiempo de nada. Por lo demás excelente el profesor, todo se entiende y es muy pura vida.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '865d69512aef9e0d013ba76ea862d98868cb95f2b4bf783eb80c98e6eaae986b'::TEXT, ARRAY[1279, 1276]::BIGINT[]),
    (709::BIGINT, 'El profe se nota que sabe de lo que habla pero no lo sabe expresar y explica con presentaciones muy rápido. El curso lo hace más tedioso de lo que suele ser. A pesar de eso, es muy buena persona y explica bien de forma individual.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'f8762c16d02e3e11d57f8e1993ebf87de6bfb0b3d10d9063d905ec316b501da4'::TEXT, ARRAY[1279, 1276]::BIGINT[]),
    (709::BIGINT, 'Explica con presentaciones pero las explica muy bien. Se aprende bastante. Además brinda ayuda para otras materias.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '8c461d30a728a7f9977863374405ade5e81f97d764596ee5cdd09300c7128141'::TEXT, ARRAY[1279, 1276]::BIGINT[]),
    (709::BIGINT, 'Explica con diapositivas, pero las explica bien, demuestra de donde salen las cosas, explica los funcionamientos de los circuitos y sus limitaciones. Pero no tiene buena comunicación oral, entonces la clase se hace larga y tediosa. No regala ni una milésima de punto, si cayó en repo va a repo.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '2331cc01ef1573e2249963d986b31f6fe369e8b5a1bd2201c4a6c400e7d4334e'::TEXT, ARRAY[1279, 1276]::BIGINT[]),
    (709::BIGINT, 'Buen profe, aunque los quices son dificiles'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, '9ec18d930b03c0f5e168d91d2ffd63df598fb4841c7cc74cd1195e00e57dd645'::TEXT, ARRAY[3050]::BIGINT[]),
    (709::BIGINT, 'Buen profe, hace los quices muy duros, no es una materia fácil hay que ponerle.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-20T00:00:00+00:00'::TIMESTAMPTZ, '64048cd336f2b109238d182348ed176a9998088e768fac84c43798d3d3b37ea5'::TEXT, ARRAY[3050]::BIGINT[]),
    (709::BIGINT, 'Explica muy bien! Las comprobaciones prácticas y los quices son duros, hay que estudiar mucho los cuestionarios previos. Es uno de los pocos profesores donde realmente se aprende. Altamente recomendado.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-08T00:00:00+00:00'::TIMESTAMPTZ, '81d8906ffe8cd7a514460751ea0c7e0307381381eb5fd0ab7fb3209c457214f1'::TEXT, ARRAY[3050]::BIGINT[]),
    (709::BIGINT, 'Muy buena persona y profesor. Sin embargo, los quices y exámenes son muy difíciles.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'ab674a9ed8863950e7f1d008b42a300a4d27371ee35715006f4351af56b7ddb2'::TEXT, ARRAY[3050]::BIGINT[]),
    (709::BIGINT, 'Muy buen profe explica muy bien y ayuda en lo que se ocupe, nada los quices y los examenes si son un poco duros'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-02T00:00:00+00:00'::TIMESTAMPTZ, '3dae9e6fae3128201a93ddc48b4b15c642a502e7534418570223389ebb2f0746'::TEXT, ARRAY[3050]::BIGINT[]),
    (709::BIGINT, 'Buen profe. Hace los quices muy duros, hay que estudiar mucho los cuestionarios previos para salir bien. Pero ayuda mucho y le explica las veces que tiene que ser'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'd478895d49a715afd3ff2044e64a289945bb9783c3a15aa89cbce4b5b98a2981'::TEXT, ARRAY[3050]::BIGINT[]),
    (709::BIGINT, 'Buen profe, de tener cuidado en quices y examen, pero explica bien y ayuda bastante.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-26T00:00:00+00:00'::TIMESTAMPTZ, '290db58dd0b2bd72aa850090f0f06bb0e13ddf3eca0faa47f082937e3ca1f879'::TEXT, ARRAY[3050]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
